uments are available to anyone with their link. Private documents are owner-only.'))?></p><p class="hint"><?=e(t('Une traduction vide utilise automatiquement l’autre langue.','An empty translation automatically uses the other language.'))?></p></section></div><aside class="editor-sidebar"><section class="panel"><h2><?=e(t('Publication','Publishing'))?></h2><label><?=e(t('Statut','Status'))?><select name="status"><?php foreach(['draft'=>t('Brouillon','Draft'),'published'=>t('Publié / programmé','Published / scheduled'),'private'=>t('Privé','Private'),'trash'=>t('Corbeille','Trash')] as $k=>$label):?><option value="<?=$k?>" <?=($v['status'] ?? 'draft')===$k?'selected':''?>><?=e($label)?></option><?php endforeach;?></select></label><label><?=e(t('Date de publication (UTC)','Publish date (UTC)'))?><input name="publish_at" type="datetime-local" value="<?=e(is_string($v['publish_at'] ?? null)?$v['publish_at']:gmdate('Y-m-d\TH:i',$v['publish_at'] ?? time()))?>"></label><label><?=e(t('Lien / slug','Link / slug'))?><input name="slug" maxlength="100" value="<?=e($get('slug'))?>" placeholder="mon-article"></label><label><?=e(t('Mots-clés, séparés par virgules','Tags, separated by commas'))?><input name="tags" maxlength="500" value="<?=e($tags)?>"></label><label class="checkbox"><input name="pinned" type="checkbox" <?=!empty($v['pinned'])?'checked':''?>><?=e(t('Épingler dans le fil','Pin to feed'))?></label><?php if($type==='page'):?><label class="checkbox"><input name="menu" type="checkbox" <?=!empty($v['menu'])?'checked':''?>><?=e(t('Afficher dans la navigation','Show in navigation'))?></label><label><?=e(t('Ordre du menu','Menu order'))?><input name="order" type="number" min="0" max="999" value="<?=e($v['order'] ?? 10)?>"></label><?php endif;?><input type="hidden" name="comments_config" value="1"><label class="checkbox"><input type="checkbox" name="comments_open" <?=($v['comments_open'] ?? true)?'checked':''?>><?=e(t('Autoriser les commentaires si leur extension est active','Allow comments when the plugin is active'))?></label><label><?=e(t('Image de couverture','Cover image'))?><?=media_select('cover',$get('cover'),$vv->state['media'])?></label><?php vv_do('editor_fields_v1',$vv,$v);?><button class="button primary full" type="submit"><?=e(t('Enregistrer','Save'))?></button><?php if($c):?><a class="button secondary full" href="<?=e(url('index.php',['preview'=>$c['id'],'lang'=>lang()]))?>" target="_blank" rel="noopener"><?=e(t('Voir sur le site','View on site'))?></a><?php endif;?></section></aside></div></form><?php if($c):?><div class="button-row editor-extras"><?=action_form('content.duplicate',t('Dupliquer en brouillon','Duplicate as draft'),['id'=>$c['id']])?><details class="panel revisions"><summary><?=count($c['revisions'])?> <?=e(t('révisions conservées','saved revisions'))?></summary><?php foreach(array_reverse($c['revisions'],true) as $n=>$r):?><div class="revision-row"><span><?=e($r['updated_at'])?> · <?=e($r['title_fr'] ?: $r['title_en'])?></span><?=action_form('content.revision',t('Restaurer','Restore'),['id'=>$c['id'],'revision'=>$n,'version'=>$c['version']],'secondary small')?></div><?php endforeach;?></details></div><?php endif; endif;?>
